// Package species holds the authored bird catalog.
//
// greenhollow.go (Greenhollow Woods roster) and regional.go (all other regions) each
// return a slice; this file assembles and validates them. Do not edit this file from
// the roster tasks — add species only in your own roster file.
package species

import (
	"fmt"
	"strings"
	"sync"

	"github.com/Rik-Stokmans/wildcall/internal/core"
)

var (
	once    sync.Once
	catalog []core.Species
	byID    map[string]int
)

func load() {
	once.Do(func() {
		catalog = append(catalog, greenhollowSpecies()...)
		catalog = append(catalog, regionalSpecies()...)
		byID = make(map[string]int, len(catalog))
		for i := range catalog {
			catalog[i].Index = i
			byID[catalog[i].ID] = i
		}
	})
}

// All returns the full catalog; Index of each entry equals its position.
// The returned slice must be treated as read-only.
func All() []core.Species { load(); return catalog }

// ByID returns a species by id.
func ByID(id string) (*core.Species, bool) {
	load()
	i, ok := byID[id]
	if !ok {
		return nil, false
	}
	return &catalog[i], true
}

// Validate checks every species against the contract vocabulary. Both roster tasks
// must keep this passing (see catalog_test.go).
func Validate(list []core.Species) []error {
	var errs []error
	bad := func(sp *core.Species, f string, a ...any) {
		errs = append(errs, fmt.Errorf("%s: %s", sp.ID, fmt.Sprintf(f, a...)))
	}
	in := func(v string, set ...string) bool {
		for _, s := range set {
			if s == v {
				return true
			}
		}
		return false
	}
	hex := func(c string) bool {
		if len(c) != 7 || c[0] != '#' {
			return false
		}
		return strings.Trim(strings.ToLower(c[1:]), "0123456789abcdef") == ""
	}
	seen := map[string]bool{}
	for i := range list {
		sp := &list[i]
		if sp.ID == "" || seen[sp.ID] {
			bad(sp, "missing or duplicate id")
		}
		seen[sp.ID] = true
		if sp.Name == "" || sp.Sci == "" || sp.Family == "" || sp.Desc == "" || sp.IDTips == "" || sp.Fact == "" {
			bad(sp, "name/sci/family/desc/idTips/fact must all be set")
		}
		if len(sp.Regions) == 0 {
			bad(sp, "no regions")
		}
		for _, r := range sp.Regions {
			if r >= core.RegionCount {
				bad(sp, "bad region %d", r)
			}
		}
		if len(sp.Habitats) == 0 {
			bad(sp, "no habitats")
		}
		for _, h := range sp.Habitats {
			if _, ok := core.HabitatFromKey(h.Habitat); !ok {
				bad(sp, "bad habitat %q", h.Habitat)
			}
		}
		if !(sp.Seasons[0] || sp.Seasons[1] || sp.Seasons[2] || sp.Seasons[3]) {
			bad(sp, "present in no season")
		}
		l := sp.Look
		if l.Length < 0.07 || l.Length > 1.6 || l.Wingspan < 0.1 || l.Wingspan > 2.6 {
			bad(sp, "implausible length/wingspan %.2f/%.2f", l.Length, l.Wingspan)
		}
		if !in(l.TailShape, "square", "forked", "fan", "pointed", "cocked") {
			bad(sp, "bad tailShape %q", l.TailShape)
		}
		if !in(l.BillShape, "cone", "thin", "dagger", "hooked", "flat", "curved", "chisel") {
			bad(sp, "bad billShape %q", l.BillShape)
		}
		if !in(l.WingShape, "rounded", "pointed", "broad", "long") {
			bad(sp, "bad wingShape %q", l.WingShape)
		}
		for _, c := range []string{l.Colors.Back, l.Colors.Belly, l.Colors.Head, l.Colors.Wing, l.Colors.Tail, l.Colors.Bill, l.Colors.Legs, l.Colors.Eye} {
			if !hex(c) {
				bad(sp, "bad colour %q", c)
			}
		}
		for _, m := range l.Marks {
			if !in(m.Kind, "breast", "cap", "mask", "eyestripe", "wingbar", "bib", "collar", "rump", "cheek", "spots", "streaks", "tailtip", "bars", "throat", "nape", "wingpatch") || !hex(m.Color) {
				bad(sp, "bad mark %v", m)
			}
		}
		if !in(sp.Move.Flight, "direct", "undulating", "soaring", "hover", "flapglide", "darting", "buoyant", "whirring") {
			bad(sp, "bad flight %q", sp.Move.Flight)
		}
		if !in(sp.Move.Ground, "hop", "walk", "wade", "swim", "cling", "none") {
			bad(sp, "bad ground %q", sp.Move.Ground)
		}
		if sp.Move.Speed <= 0 || sp.Move.FlapHz <= 0 {
			bad(sp, "speed/flapHz must be > 0")
		}
		b := sp.Behavior
		if len(b.Perches) == 0 {
			bad(sp, "no perches")
		}
		for _, p := range b.Perches {
			if _, ok := core.PerchKindFromKey(p); !ok {
				bad(sp, "bad perch %q", p)
			}
		}
		if !in(b.Feeding, "ground", "glean", "aerial", "dive", "dabble", "probe", "hunt", "trunk", "seeds", "scavenge", "plunge") {
			bad(sp, "bad feeding %q", b.Feeding)
		}
		if !in(b.Sociality, "solitary", "pair", "flock") {
			bad(sp, "bad sociality %q", b.Sociality)
		}
		if b.Territory <= 0 || b.Shyness <= 0 || b.Vocal <= 0 || b.Density <= 0 {
			bad(sp, "territory/shyness/vocal/density must be > 0")
		}
		var act float32
		for _, a := range b.Activity {
			act += a
		}
		if act <= 0 {
			bad(sp, "never active")
		}
		if len(sp.Calls) == 0 {
			bad(sp, "no calls")
		}
		for ci, c := range sp.Calls {
			if !in(c.Kind, "song", "call", "alarm", "drum", "boom") {
				bad(sp, "call %d bad kind %q", ci, c.Kind)
			}
			if !in(c.Pitch, "low", "medium", "high", "very high") {
				bad(sp, "call %d bad pitch %q", ci, c.Pitch)
			}
			if !in(c.Pattern, "repeated", "trill", "melodic", "single", "harsh", "drumming", "booming", "whistle", "chatter", "laughing") {
				bad(sp, "call %d bad pattern %q", ci, c.Pattern)
			}
			if len(c.Notes) == 0 || c.Repeat[0] < 1 || c.Repeat[1] < c.Repeat[0] || c.Loud <= 0 || c.Loud > 1 {
				bad(sp, "call %d needs notes, repeat min<=max, loud in (0,1]", ci)
			}
			for ni, n := range c.Notes {
				if !in(n.Wave, "sine", "whistle", "buzz", "trill", "noise", "click") {
					bad(sp, "call %d note %d bad wave %q", ci, ni, n.Wave)
				}
				if n.Dur <= 0 || n.F0 < 40 || n.F0 > 11000 || n.F1 < 40 || n.F1 > 11000 || n.Amp <= 0 || n.Amp > 1 {
					bad(sp, "call %d note %d out of range", ci, ni)
				}
			}
		}
		t := sp.Traits
		if !in(t.Size, "tiny", "small", "medium", "large", "huge") {
			bad(sp, "bad size %q", t.Size)
		}
		if !in(t.Shape, "songbird", "finch", "tit", "thrush", "warbler", "woodpecker", "owl", "raptor", "duck", "heron", "wader", "gull", "corvid", "swallow", "kingfisher", "rail", "seabird", "pigeon", "lark", "wagtail", "grouse", "treecreeper") {
			bad(sp, "bad shape %q", t.Shape)
		}
		if t.Primary == "" || t.Secondary == "" || t.Marking == "" || t.Bill == "" || t.Flight != sp.Move.Flight {
			bad(sp, "traits incomplete, or traits.flight != move.flight")
		}
		if sp.Difficulty < 1 || sp.Difficulty > 5 {
			bad(sp, "difficulty must be 1..5")
		}
	}
	for i := range list {
		for _, s := range list[i].Similar {
			if !seen[s] {
				errs = append(errs, fmt.Errorf("%s: similar species %q not in catalog", list[i].ID, s))
			}
		}
	}
	return errs
}
